    83	func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
    84		if strings.TrimSpace(session.SessionRef) == "" {
    85			return errMissingSessionRef
    86		}
    87		// Never truncate a real transcript with an empty snapshot. ReadSession
    88		// yields nil NativeData when the native transcript is missing, so an empty
    89		// payload means "nothing was captured", not "the session is empty" — and
    90		// writing it would destroy Grok's own history, which redaction cannot undo.
    91		if len(bytes.TrimSpace(session.NativeData)) == 0 {
    92			return errEmptySessionData
    93		}
    94		sessionDir := filepath.Dir(session.SessionRef)
    95		if err := os.MkdirAll(sessionDir, 0o700); err != nil {
    96			return err
    97		}
    98		if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
    99			return err
   100		}
   101		return writeSessionSummary(sessionDir, session)
   102	}
   103	
   104	// writeSessionSummary synthesizes the summary.json that Grok requires to
   105	// recognize a session directory.
   106	//
   107	// Restoring chat_history.jsonl alone is not enough: Grok's session lookup
   108	// ignores a directory with no summary.json, reports "Session not found
   109	// locally", and falls back to the remote registry (404 for a local-only
   110	// session). Worse, `grok --continue` then silently resumes a different, older
   111	// session instead of failing, so a bad restore looks like a good one.
   112	//
   113	// An existing summary.json is left alone so a restore over a live session
   114	// does not clobber Grok's own metadata.
   115	func writeSessionSummary(sessionDir string, session protocol.AgentSessionJSON) error {
   116		path := filepath.Join(sessionDir, "summary.json")
   117		if _, err := os.Stat(path); err == nil {
   118			return nil
   119		} else if !errors.Is(err, os.ErrNotExist) {
   120			return err
   121		}
   122	
   123		sessionID := strings.TrimSpace(session.SessionID)
   124		if sessionID == "" {
   125			sessionID = filepath.Base(sessionDir)
   126		}
   127		cwd := strings.TrimSpace(session.RepoPath)
   128		if cwd == "" {
   129			cwd = protocol.RepoRoot()
   130		}
   131		timestamp := normalizedSummaryTime(session.StartTime)
   132		count := countTranscriptLines(session.NativeData)
   133	
   134		messages, _ := readChatHistoryMessagesFromBytes(session.NativeData)
   135		summary := grokSessionSummary{
   136			Info:              grokSessionSummaryInfo{ID: sessionID, CWD: cwd},
   137			SessionSummary:    restoredSummaryTitle,
   138			GeneratedTitle:    restoredSummaryTitle,
   139			CurrentModelID:    lastModelID(messages),
   140			CreatedAt:         timestamp,
   141			UpdatedAt:         timestamp,
   142			LastActiveAt:      timestamp,
   143			NumMessages:       count,
   144			NumChatMessages:   count,
   145			ChatFormatVersion: 1,
   146			// Grok records git_root_dir with a trailing separator.
   147			GitRootDir: strings.TrimSuffix(cwd, "/") + "/",
   148			GrokHome:   grokHome(),
   149		}
   150		data, err := json.Marshal(summary)
   151		if err != nil {
   152			return err
   153		}
   154		return os.WriteFile(path, data, 0o600)
   155	}
