   157	// normalizedSummaryTime returns an RFC3339 timestamp Grok will accept.
   158	//
   159	// Entire sends an unset StartTime as a formatted zero time rather than an
   160	// empty string, and Grok rejects a summary carrying a year-1 timestamp with
   161	// "Session does not exist", so treat unparseable and zero values as absent.
   162	func normalizedSummaryTime(value string) string {
   163		parsed, err := time.Parse(time.RFC3339, strings.TrimSpace(value))
   164		if err != nil || parsed.IsZero() || parsed.Year() < 2000 {
   165			return time.Now().UTC().Format(time.RFC3339)
   166		}
   167		return parsed.UTC().Format(time.RFC3339)
   168	}
