   188	func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
   189		if maxSize <= 0 {
   190			return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
   191		}
   192		if len(content) == 0 {
   193			return [][]byte{{}}, nil
   194		}
   195		var chunks [][]byte
   196		for start := 0; start < len(content); start += maxSize {
   197			end := start + maxSize
   198			if end > len(content) {
   199				end = len(content)
   200			}
   201			chunk := make([]byte, end-start)
   202			copy(chunk, content[start:end])
   203			chunks = append(chunks, chunk)
   204		}
   205		return chunks, nil
   206	}
