   368	func safeFilename(name string) string {
   369		name = strings.TrimSpace(name)
   370		if name == "" {
   371			return stubSessionID
   372		}
   373		var b strings.Builder
   374		for _, r := range name {
   375			switch {
   376			case r == '-' || r == '_' || r == '.':
   377				b.WriteRune(r)
   378			case r >= '0' && r <= '9':
   379				b.WriteRune(r)
   380			case r >= 'a' && r <= 'z':
   381				b.WriteRune(r)
   382			case r >= 'A' && r <= 'Z':
   383				b.WriteRune(r)
   384			default:
   385				if unicode.IsLetter(r) || unicode.IsNumber(r) {
   386					b.WriteRune(r)
   387				} else {
   388					b.WriteByte('_')
   389				}
   390			}
   391		}
   392		out := strings.Trim(b.String(), "._")
   393		if out == "" {
   394			return stubSessionID
   395		}
   396		return out
   397	}
