   399	func readSidecarRecords(path string) ([]sidecarRecord, error) {
   400		f, err := os.Open(path)
   401		if err != nil {
   402			return nil, err
   403		}
   404		defer func() { _ = f.Close() }()
   405	
   406		var records []sidecarRecord
   407		scanner := bufio.NewScanner(f)
   408		for scanner.Scan() {
   409			line := strings.TrimSpace(scanner.Text())
   410			if line == "" {
   411				continue
   412			}
   413			var record sidecarRecord
   414			if err := json.Unmarshal([]byte(line), &record); err != nil {
   415				return nil, err
   416			}
   417			records = append(records, record)
   418		}
   419		return records, scanner.Err()
   420	}
