   422	func modifiedFilesFromRecords(records []sidecarRecord) []string {
   423		seen := map[string]struct{}{}
   424		for _, record := range records {
   425			if !isFileModificationTool(record.ToolName) {
   426				continue
   427			}
   428			for _, path := range pathsFromToolInput(record.ToolInput, record.ToolName) {
   429				normalized := strings.TrimSpace(path)
   430				if normalized == "" {
   431					continue
   432				}
   433				seen[normalized] = struct{}{}
   434			}
   435		}
   436		files := make([]string, 0, len(seen))
   437		for file := range seen {
   438			files = append(files, file)
   439		}
   440		sort.Strings(files)
   441		return files
   442	}
