   444	func isFileModificationTool(name string) bool {
   445		if _, ok := fileModificationTools[name]; ok {
   446			return true
   447		}
   448		lower := strings.ToLower(name)
   449		return strings.Contains(lower, "write") ||
   450			strings.Contains(lower, "edit") ||
   451			strings.Contains(lower, "replace") ||
   452			strings.Contains(lower, "shell") ||
   453			strings.Contains(lower, "bash")
   454	}
