   456	func pathsFromToolInput(raw json.RawMessage, toolName string) []string {
   457		if len(bytes.TrimSpace(raw)) == 0 {
   458			return nil
   459		}
   460		var value map[string]any
   461		if err := json.Unmarshal(raw, &value); err != nil {
   462			return nil
   463		}
   464		var paths []string
   465		collectPathValues(value, &paths)
   466		if command, ok := value["command"].(string); ok && isShellTool(toolName) {
   467			paths = append(paths, pathsFromShellCommand(command)...)
   468		}
   469		return paths
   470	}
   471	
   472	func collectPathValues(value any, paths *[]string) {
   473		switch v := value.(type) {
   474		case map[string]any:
   475			for key, item := range v {
   476				if isCommonPathKey(key) {
   477					*paths = append(*paths, stringValues(item)...)
   478				}
   479				collectPathValues(item, paths)
   480			}
   481		case []any:
   482			for _, item := range v {
   483				collectPathValues(item, paths)
   484			}
   485		}
   486	}
   487	
   488	func isCommonPathKey(key string) bool {
   489		for _, candidate := range commonPathKeys {
   490			if strings.EqualFold(key, candidate) {
   491				return true
   492			}
   493		}
   494		return false
   495	}
   496	
   497	func stringValues(value any) []string {
   498		switch v := value.(type) {
   499		case string:
   500			if strings.TrimSpace(v) == "" {
   501				return nil
   502			}
   503			return []string{v}
   504		case []any:
   505			var out []string
   506			for _, item := range v {
   507				out = append(out, stringValues(item)...)
   508			}
   509			return out
   510		default:
   511			return nil
   512		}
   513	}
   514	
   515	func isShellTool(toolName string) bool {
   516		lower := strings.ToLower(toolName)
   517		return lower == "bash" || lower == "shell" || strings.Contains(lower, "shell")
   518	}
   519	
   520	var shellPathPatterns = []*regexp.Regexp{
   521		regexp.MustCompile(`(?:^|\s)(?:>|>>)\s*['"]?([^'"\s;&|]+)`),
   522		regexp.MustCompile(`(?:^|\s)tee\s+(?:-a\s+)?['"]?([^'"\s;&|]+)`),
   523		regexp.MustCompile(`(?:^|\s)touch\s+['"]?([^'"\s;&|]+)`),
   524	}
   525	
   526	func pathsFromShellCommand(command string) []string {
   527		var paths []string
   528		for _, pattern := range shellPathPatterns {
   529			matches := pattern.FindAllStringSubmatch(command, -1)
   530			for _, match := range matches {
   531				if len(match) > 1 {
   532					paths = append(paths, strings.Trim(match[1], `"'`))
   533				}
   534			}
   535		}
   536		return paths
   537	}
