    48	func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
    49		data, err := os.ReadFile(sessionRef)
    50		if err != nil {
    51			return protocol.CompactTranscriptResponse{}, err
    52		}
    53		compacted, err := compactTranscriptBytes(data)
    54		if err != nil {
