    60	func compactTranscriptBytes(data []byte) ([]byte, error) {
    61		if looksLikeChatHistory(data) {
    62			return compactChatHistoryBytes(data)
    63		}
    64		records := parseSidecarRecords(data)
    65		var buf bytes.Buffer
    66		for _, record := range records {
    67			switch record.Event {
    68			case "UserPromptSubmit":
    69				if record.Prompt == "" {
    70					continue
    71				}
    72				if err := writeCompactLine(&buf, compactLine{
    73					V:          1,
    74					Agent:      AgentName,
    75					CLIVersion: compactCLIVersion,
    76					Type:       roleUser,
    77					TS:         record.TS,
    78					Content:    []compactUserTextBlock{{Text: record.Prompt}},
    79				}); err != nil {
    80					return nil, err
    81				}
    82			case "PostToolUse", "PostToolUseFailure":
    83				block := compactToolUseBlock{
    84					Type:  "tool_use",
    85					ID:    record.ToolUseID,
    86					Name:  record.ToolName,
    87					Input: decodeRawObject(record.ToolInput),
    88				}
    89				if len(record.ToolResponse) > 0 {
    90					block.Result = &compactToolResult{Output: string(record.ToolResponse), Status: "success"}
    91				}
    92				if record.Error != "" || record.ErrorDetails != "" {
    93					block.Result = &compactToolResult{Output: record.Error + " " + record.ErrorDetails, Status: "error"}
    94				}
    95				if err := writeCompactLine(&buf, compactLine{
    96					V:          1,
    97					Agent:      AgentName,
    98					CLIVersion: compactCLIVersion,
    99					Type:       roleAssistant,
   100					TS:         record.TS,
   101					ID:         record.ToolUseID,
   102					Content:    []any{block},
   103				}); err != nil {
   104					return nil, err
   105				}
   106			case "Stop", "StopFailure":
   107				text := record.LastAssistantMessage
   108				if text == "" {
   109					text = record.ErrorDetails
   110				}
   111				if text == "" {
   112					continue
   113				}
   114				if err := writeCompactLine(&buf, compactLine{
   115					V:          1,
   116					Agent:      AgentName,
   117					CLIVersion: compactCLIVersion,
   118					Type:       roleAssistant,
   119					TS:         record.TS,
   120					Content:    []compactAssistantTextBlock{{Type: "text", Text: text}},
   121				}); err != nil {
   122					return nil, err
   123				}
   124			}
   125		}
   126		if buf.Len() == 0 {
   127			return nil, errors.New("compact transcript produced no output")
   128		}
   129		return buf.Bytes(), nil
   130	}
   131	
   132	// chatHistoryTypes are the line types only a Grok chat_history.jsonl carries.
   133	// Entire's own sidecar records use an "event" field instead of "type".
   134	var chatHistoryTypes = map[string]bool{
   135		roleUser: true, roleAssistant: true, roleSystem: true,
   136		"reasoning": true, "tool_result": true,
   137	}
   138	
   139	// looksLikeChatHistory decides which parser to use by decoding line types rather
   140	// than substring-matching the raw bytes. A byte match is whitespace-sensitive
   141	// (`"type": "user"` with a space would miss) and can be fooled by a checkpoint
   142	// slice whose lines happen not to contain the literal it looks for.
   143	func looksLikeChatHistory(data []byte) bool {
   144		scanner := bufio.NewScanner(bytes.NewReader(data))
   145		scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
   146		for scanner.Scan() {
   147			line := bytes.TrimSpace(scanner.Bytes())
   148			if len(line) == 0 {
   149				continue
   150			}
   151			var probe struct {
   152				Type  string `json:"type"`
   153				Event string `json:"event"`
   154			}
   155			if err := json.Unmarshal(line, &probe); err != nil {
   156				continue
   157			}
   158			if probe.Event != "" {
   159				return false
   160			}
   161			if chatHistoryTypes[probe.Type] {
   162				return true
   163			}
   164		}
   165		return false
   166	}
   167	
   168	// parseSidecarRecords parses Entire's own sidecar JSONL, skipping any line it
   169	// cannot decode so a truncated slice does not fail the whole transcript.
   170	func parseSidecarRecords(data []byte) []sidecarRecord {
   171		lines := bytes.Split(data, []byte("\n"))
   172		records := make([]sidecarRecord, 0, len(lines))
   173		for _, line := range lines {
   174			line = bytes.TrimSpace(line)
   175			if len(line) == 0 {
   176				continue
   177			}
   178			var record sidecarRecord
   179			if err := json.Unmarshal(line, &record); err != nil {
   180				// Tolerate a truncated first/last line from checkpoint scoping or a
   181				// concurrent write, the same way the chat-history scanner does.
   182				continue
   183			}
   184			records = append(records, record)
   185		}
   186		return records
   187	}
   188	
   189	func writeCompactLine(buf *bytes.Buffer, line compactLine) error {
   190		data, err := json.Marshal(line)
   191		if err != nil {
   192			return err
   193		}
   194		buf.Write(data)
   195		buf.WriteByte('\n')
   196		return nil
   197	}
   198	
   199	func decodeRawObject(raw json.RawMessage) any {
   200		if len(raw) == 0 {
   201			return nil
   202		}
   203		var value any
   204		if err := json.Unmarshal(raw, &value); err != nil {
   205			return string(raw)
   206		}
   207		return value
   208	}

