 15	type chatHistoryMessage struct {
 16		Type      string `json:"type"`
 17		Content   any    `json:"content"`
 18		ToolCalls []struct {
 19			ID        string `json:"id"`
 20			Name      string `json:"name"`
 21			Arguments string `json:"arguments"`
 22		} `json:"tool_calls"`
 23		// PromptIndex is set by Grok only on genuine user prompts. Synthetic user
 24		// messages (system reminders, injected context) never carry it, so its
 25		// presence is the reliable signal for "the human typed this".
 26		PromptIndex *int `json:"prompt_index"`
 27		// SyntheticReason is set on Grok-injected user messages, e.g. "system_reminder".
 28		SyntheticReason string `json:"synthetic_reason"`
 29		// ToolCallID links a tool_result line back to the tool_use that produced it.
 30		ToolCallID string `json:"tool_call_id"`
 31		// Summary carries the human-readable reasoning summary on reasoning lines.
 32		Summary any `json:"summary"`
 33		// ModelID is stamped on assistant and reasoning lines.
 34		ModelID string `json:"model_id"`
 35	}
