 37	// lastModelID returns the most recent model stamped on the transcript. Grok
 38	// rejects a restored session whose summary.json has no current_model_id.
 39	func lastModelID(messages []chatHistoryMessage) string {
 40		for i := len(messages) - 1; i >= 0; i-- {
 41			if id := strings.TrimSpace(messages[i].ModelID); id != "" {
 42				return id
 43			}
 44		}
 45		return ""
 46	}
