 98	func promptsFromChatHistory(messages []chatHistoryMessage, offset int) []string {
 99		if offset < 0 {
100			offset = 0
101		}
102		if offset > len(messages) {
103			offset = len(messages)
104		}
105		scoped := messages[offset:]
106		marked := hasPromptIndex(scoped)
107		var prompts []string
108		for _, message := range scoped {
109			if !isPromptCandidate(message, marked) {
110				continue
111			}
112			for _, text := range messageTextParts(message.Content) {
113				if prompt := extractUserQuery(text); prompt != "" {
114					prompts = append(prompts, prompt)
115				}
116			}
117		}
118		return prompts
119	}
