121	// hasPromptIndex reports whether Grok tagged any user line with prompt_index.
122	// Versions that emit the tag let us identify real prompts exactly; for any that
123	// do not, callers fall back to the <user_query> heuristic.
124	func hasPromptIndex(messages []chatHistoryMessage) bool {
125		for _, message := range messages {
126			if message.Type == roleUser && message.PromptIndex != nil {
127				return true
128			}
129		}
130		return false
131	}
132	
133	func isPromptCandidate(message chatHistoryMessage, marked bool) bool {
134		if message.Type != roleUser || message.SyntheticReason != "" {
135			return false
136		}
137		if marked {
138			return message.PromptIndex != nil
139		}
140		return true
141	}
