143	func summaryFromChatHistory(messages []chatHistoryMessage) (string, bool) {
144		for i := len(messages) - 1; i >= 0; i-- {
145			message := messages[i]
146			if message.Type != roleAssistant {
147				continue
148			}
149			if text, ok := assistantText(message); ok && strings.TrimSpace(text) != "" {
150				return strings.TrimSpace(text), true
151			}
152		}
153		return "", false
154	}
