156	func modifiedFilesFromChatHistory(messages []chatHistoryMessage, offset int) []string {
157		if offset < 0 {
158			offset = 0
159		}
160		if offset > len(messages) {
161			offset = len(messages)
162		}
163		seen := map[string]struct{}{}
164		for _, message := range messages[offset:] {
165			if message.Type != roleAssistant {
166				continue
167			}
168			for _, call := range message.ToolCalls {
169				if !isFileModificationTool(call.Name) {
170					continue
171				}
172				for _, path := range pathsFromToolArguments(call.Name, call.Arguments) {
173					if path = strings.TrimSpace(path); path != "" {
174						seen[path] = struct{}{}
175					}
176				}
177			}
178		}
179		files := make([]string, 0, len(seen))
180		for file := range seen {
181			files = append(files, file)
182		}
183		sort.Strings(files)
184		return files
185	}
