187	func messageTextParts(content any) []string {
188		switch value := content.(type) {
189		case string:
190			if strings.TrimSpace(value) == "" {
191				return nil
192			}
193			return []string{value}
194		case []any:
195			var parts []string
196			for _, item := range value {
197				if block, ok := item.(map[string]any); ok {
198					if text, ok := block["text"].(string); ok && strings.TrimSpace(text) != "" {
199						parts = append(parts, text)
200					}
201				}
202			}
203			return parts
204		default:
205			return nil
206		}
207	}
208	
209	// unwrapUserQuery strips the <user_query> wrapper Grok puts around the prompt it
210	// hands to UserPromptSubmit hooks. Passing it through verbatim leaves the markup
211	// in checkpoint titles, and renders the checkpoint Intent as literally
212	// "<user_query>". Text without the wrapper is returned trimmed.
213	func unwrapUserQuery(text string) string {
214		if match := userQueryPattern.FindStringSubmatch(text); len(match) > 1 {
215			return strings.TrimSpace(match[1])
216		}
217		return strings.TrimSpace(text)
218	}
219	
220	func extractUserQuery(text string) string {
221		if match := userQueryPattern.FindStringSubmatch(text); len(match) > 1 {
222			return strings.TrimSpace(match[1])
223		}
224		// Grok injects context into the user role. Without prompt_index to go on,
225		// drop the wrappers it uses so they don't surface as user prompts.
226		for _, marker := range []string{"<user_info>", "<rules>", "<system-reminder>"} {
227			if strings.Contains(text, marker) {
228				return ""
229			}
230		}
231		trimmed := strings.TrimSpace(text)
232		if trimmed == "" {
233			return ""
234		}
235		return trimmed
236	}
237	
238	func assistantText(message chatHistoryMessage) (string, bool) {
239		switch value := message.Content.(type) {
240		case string:
241			return strings.TrimSpace(value), value != ""
242		default:
243			parts := messageTextParts(message.Content)
244			if len(parts) == 0 {
245				return "", false
246			}
247			return strings.TrimSpace(parts[0]), true
248		}
249	}
