251	func pathsFromToolArguments(toolName, raw string) []string {
252		raw = strings.TrimSpace(raw)
253		if raw == "" {
254			return nil
255		}
256		var value map[string]any
257		if err := json.Unmarshal([]byte(raw), &value); err != nil {
258			return nil
259		}
260		var paths []string
261		collectPathValues(value, &paths)
262		if command, ok := value["command"].(string); ok && isShellTool(toolName) {
263			paths = append(paths, pathsFromShellCommand(command)...)
264		}
265		return paths
266	}
