268	func isNativeTranscript(path string) bool {
269		return strings.HasSuffix(path, nativeTranscriptFile)
270	}
271	
272	func readTranscriptEntries(path string) ([]sidecarRecord, error) {
273		if !isNativeTranscript(path) {
274			return readSidecarRecords(path)
275		}
276		messages, err := readChatHistoryMessages(path)
277		if err != nil {
278			return nil, err
279		}
280		marked := hasPromptIndex(messages)
281		records := make([]sidecarRecord, 0, len(messages))
282		for _, message := range messages {
283			record := sidecarRecord{Agent: AgentName}
284			switch message.Type {
285			case roleUser:
286				if !isPromptCandidate(message, marked) {
287					continue
288				}
289				record.Event = "UserPromptSubmit"
290				for _, text := range messageTextParts(message.Content) {
291					if prompt := extractUserQuery(text); prompt != "" {
292						record.Prompt = prompt
293						break
294					}
295				}
296				if record.Prompt == "" {
297					continue
298				}
299			case roleAssistant:
300				if text, ok := assistantText(message); ok {
301					record.Event = "Stop"
302					record.LastAssistantMessage = text
303				}
304				for _, call := range message.ToolCalls {
305					toolRecord := sidecarRecord{
306						Agent:     AgentName,
307						Event:     "PostToolUse",
308						ToolName:  call.Name,
309						ToolUseID: call.ID,
310					}
311					if len(strings.TrimSpace(call.Arguments)) > 0 {
312						toolRecord.ToolInput = json.RawMessage(call.Arguments)
313					}
314					records = append(records, toolRecord)
315				}
316				if record.Event != "" {
317					records = append(records, record)
318				}
319				continue
320			default:
321				continue
322			}
323			if record.Event != "" {
324				records = append(records, record)
325			}
326		}
327		return records, nil
328	}
