330	func compactChatHistoryBytes(data []byte) ([]byte, error) {
331		messages, err := readChatHistoryMessagesFromBytes(data)
332		if err != nil {
333			return nil, err
334		}
335		marked := hasPromptIndex(messages)
336		results := toolResultsByCallID(messages)
337		consumed := make(map[string]bool, len(results))
338		var buf bytes.Buffer
339		for _, message := range messages {
340			switch message.Type {
341			case "tool_result":
342				// A checkpoint slice can start after the assistant line that issued
343				// the call, orphaning its result. Emit it standalone so the tool
344				// output still reaches the summarizer.
345				result, ok := results[message.ToolCallID]
346				if !ok || consumed[message.ToolCallID] {
347					continue
348				}
349				consumed[message.ToolCallID] = true
350				if err := writeCompactLine(&buf, compactLine{
351					V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
352					ID: message.ToolCallID,
353					Content: []any{compactToolUseBlock{
354						Type: "tool_use", ID: message.ToolCallID, Name: "unknown", Result: result,
355					}},
356				}); err != nil {
357					return nil, err
358				}
359			case roleUser:
360				if !isPromptCandidate(message, marked) {
361					continue
362				}
363				for _, text := range messageTextParts(message.Content) {
364					if prompt := extractUserQuery(text); prompt != "" {
365						if err := writeCompactLine(&buf, compactLine{
366							V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleUser,
367							Content: []compactUserTextBlock{{Text: prompt}},
368						}); err != nil {
369							return nil, err
370						}
371					}
372				}
373			case "reasoning":
374				// Keep the plaintext reasoning summary. encrypted_content is
375				// deliberately dropped: it is opaque to a summarizer and is the
376				// field redaction mangles.
377				text := reasoningSummaryText(message.Summary)
378				if text == "" {
379					continue
380				}
381				if err := writeCompactLine(&buf, compactLine{
382					V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
383					Content: []compactAssistantTextBlock{{Type: "thinking", Text: text}},
384				}); err != nil {
385					return nil, err
386				}
387			case roleAssistant:
388				for _, call := range message.ToolCalls {
389					block := compactToolUseBlock{
390						Type: "tool_use", ID: call.ID, Name: call.Name,
391						Input: decodeRawObject(json.RawMessage(call.Arguments)),
392					}
393					if result, ok := results[call.ID]; ok {
394						block.Result = result
395						consumed[call.ID] = true
396					}
397					if err := writeCompactLine(&buf, compactLine{
398						V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
399						ID: call.ID, Content: []any{block},
400					}); err != nil {
401						return nil, err
402					}
403				}
404				if text, ok := assistantText(message); ok && text != "" {
405					if err := writeCompactLine(&buf, compactLine{
406						V: 1, Agent: AgentName, CLIVersion: compactCLIVersion, Type: roleAssistant,
407						Content: []compactAssistantTextBlock{{Type: "text", Text: text}},
408					}); err != nil {
409						return nil, err
410					}
411				}
412			}
413		}
414		if buf.Len() == 0 {
415			return nil, errors.New("compact transcript produced no output")
416		}
417		return buf.Bytes(), nil
418	}
419	
420	func readChatHistoryMessagesFromBytes(data []byte) ([]chatHistoryMessage, error) {
421		return scanChatHistory(bytes.NewReader(data))
422	}
423	
424	// toolResultsByCallID indexes tool_result lines so each tool_use block can carry
425	// its output. Grok writes results as separate lines keyed by tool_call_id; without
426	// this the compacted transcript shows every call with no result.
427	func toolResultsByCallID(messages []chatHistoryMessage) map[string]*compactToolResult {
428		results := make(map[string]*compactToolResult)
429		for _, message := range messages {
430			if message.Type != "tool_result" || message.ToolCallID == "" {
431				continue
432			}
433			parts := messageTextParts(message.Content)
434			if len(parts) == 0 {
435				if text, ok := message.Content.(string); ok && strings.TrimSpace(text) != "" {
436					parts = []string{text}
437				}
438			}
439			results[message.ToolCallID] = &compactToolResult{
440				Output: strings.Join(parts, "\n"),
441				Status: "success",
442			}
443		}
444		return results
445	}
446	
447	// reasoningSummaryText pulls plain text out of a reasoning line's summary, which
448	// Grok writes as a list of {type: summary_text, text: ...} blocks.
449	func reasoningSummaryText(summary any) string {
450		switch value := summary.(type) {
451		case string:
452			return strings.TrimSpace(value)
453		case []any:
454			var parts []string
455			for _, item := range value {
456				block, ok := item.(map[string]any)
457				if !ok {
458					continue
459				}
460				if text, ok := block["text"].(string); ok && strings.TrimSpace(text) != "" {
461					parts = append(parts, strings.TrimSpace(text))
462				}
463			}
464			return strings.Join(parts, "\n")
465		default:
466			return ""
467		}
468	}
469	
470	// sanitizeTranscriptForStorage removes Grok's opaque reasoning payloads from a
471	// copy of the transcript before Entire stores it.
472	//
473	// Grok stamps each reasoning line with an "encrypted_content" blob of
474	// high-entropy base64. Two reasons not to store it. It is big: a
475	// reasoning-heavy session produced values up to 12 KB, 15% of the transcript,
476	// and Entire re-stores the transcript on every checkpoint. And its name does not
477	// match the "*signature" rule in the CLI redactor, so the entropy scanner
478	// rewrites it to REDACTED, which makes the session unreplayable ("This session's
479	// conversation history is incompatible with the current model"). Grok replays
480	// fine when the field is absent, so dropping it beats trying to preserve it.
481	//
482	// This mirrors the built-in Codex agent's SanitizeTranscriptForStorage. The
483	// external agent protocol exposes no sanitizer hook, so it runs in the adapter's
484	// read paths instead. Grok's own chat_history.jsonl is never modified here.
485	func sanitizeTranscriptForStorage(data []byte) []byte {
486		// A transcript without the marker cannot change, so skip parsing entirely.
487		if !bytes.Contains(data, []byte(encryptedContentKey)) {
488			return data
489		}
490	
491		var out bytes.Buffer
492		out.Grow(len(data))
493		scanner := bufio.NewScanner(bytes.NewReader(data))
494		scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
495		for scanner.Scan() {
496			out.Write(sanitizeTranscriptLine(scanner.Bytes()))
497			out.WriteByte('\n')
498		}
499		if scanner.Err() != nil {
500			// Prefer the unsanitized transcript over a truncated one.
501			return data
502		}
503		return out.Bytes()
504	}
505	
506	// sanitizeTranscriptLine strips encryptedContentKey from a single reasoning line,
507	// returning the line unchanged in every other case.
508	//
509	// Callers rely on one output line per input line. Entire counts checkpoint
510	// offsets in messages (see chatHistoryPosition), so dropping a line would shift
511	// every offset after it. An unparseable line is therefore kept verbatim rather
512	// than discarded: a scoped checkpoint slice can begin mid-line.
513	func sanitizeTranscriptLine(line []byte) []byte {
514		trimmed := bytes.TrimSpace(line)
515		if len(trimmed) == 0 || !bytes.Contains(trimmed, []byte(encryptedContentKey)) {
516			return line
517		}
518		var message map[string]any
519		if err := json.Unmarshal(trimmed, &message); err != nil {
520			return line
521		}
522		if messageType, _ := message[roleTypeKey].(string); messageType != roleReasoning {
523			return line
524		}
525		if _, ok := message[encryptedContentKey]; !ok {
526			return line
527		}
528		delete(message, encryptedContentKey)
529		encoded, err := json.Marshal(message)
530		if err != nil {
531			return line
532		}
533		return encoded
534	}

