 21	func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
 22		raw, err := parseHookInput(input)
 23		if err != nil {
 24			return nil, err
 25		}
 26		raw.HookEventName = grokEventName(hookName, raw.HookEventName, raw.HookEventNameCamel)
 27		normalizeRawHook(&raw, hookName)
 28	
 29		repoPath := raw.CWD
 30		if strings.TrimSpace(repoPath) == "" {
 31			repoPath = protocol.RepoRoot()
 32		}
 33		sessionRef := a.resolveSessionRef(raw.SessionID, repoPath)
 34		if err := a.writeSessionMarker(raw, sessionRef); err != nil {
 35			return nil, err
 36		}
 37		metadata := hookMetadata(raw)
 38	
 39		switch hookName {
 40		case HookNameSessionStart:
 41			return &protocol.EventJSON{
 42				Type:       1,
 43				SessionID:  raw.SessionID,
 44				SessionRef: sessionRef,
 45				Model:      raw.Model,
 46				Timestamp:  raw.Timestamp,
 47				Metadata:   metadata,
 48			}, nil
 49		case HookNameUserPromptSubmit:
 50			prompt := unwrapUserQuery(raw.Prompt)
 51			if prompt == "" {
 52				return nil, nil
 53			}
 54			return &protocol.EventJSON{
 55				Type:       2,
 56				SessionID:  raw.SessionID,
 57				SessionRef: sessionRef,
 58				Prompt:     prompt,
 59				Model:      raw.Model,
 60				Timestamp:  raw.Timestamp,
 61				Metadata:   metadata,
 62			}, nil
 63		case HookNameStop, HookNameStopCancelled:
 64			return &protocol.EventJSON{
 65				Type:            3,
 66				SessionID:       raw.SessionID,
 67				SessionRef:      sessionRef,
 68				Model:           raw.Model,
 69				Timestamp:       raw.Timestamp,
 70				ResponseMessage: raw.LastAssistantMessage,
 71				Metadata:        metadata,
 72			}, nil
 73		case HookNameStopFailure:
 74			return &protocol.EventJSON{
 75				Type:            3,
 76				SessionID:       raw.SessionID,
 77				SessionRef:      sessionRef,
 78				Model:           raw.Model,
 79				Timestamp:       raw.Timestamp,
 80				ResponseMessage: raw.ErrorDetails,
 81				Metadata:        metadata,
 82			}, nil
 83		case HookNameSessionEnd:
 84			return &protocol.EventJSON{
 85				Type:       5,
 86				SessionID:  raw.SessionID,
 87				SessionRef: sessionRef,
 88				Timestamp:  raw.Timestamp,
 89				Metadata:   metadata,
 90			}, nil
 91		case HookNamePreCompact:
 92			return &protocol.EventJSON{
 93				Type:       4,
 94				SessionID:  raw.SessionID,
 95				SessionRef: sessionRef,
 96				Timestamp:  raw.Timestamp,
 97				Metadata:   metadata,
 98			}, nil
 99		case HookNamePostCompact:
100			return &protocol.EventJSON{
101				Type:            4,
102				SessionID:       raw.SessionID,
103				SessionRef:      sessionRef,
104				Timestamp:       raw.Timestamp,
105				ResponseMessage: raw.CompactSummary,
106				Metadata:        metadata,
107			}, nil
108		case HookNamePreToolUse,
109			HookNamePostToolUse,
110			HookNamePostToolUseFailure,
111			HookNameNotification,
112			HookNamePermissionRequest,
113			HookNameSubagentStart,
114			HookNameSubagentStop:
115			return nil, nil
116		default:
117			return nil, nil
118		}
119	}
