121	func (a *Agent) InstallHooks(_ bool, force bool) (int, error) {
122		repoRoot := protocol.RepoRoot()
123		path := hooksFilePath(repoRoot)
124	
125		rawHooks, err := readHookFile(path)
126		if err != nil {
127			return 0, err
128		}
129	
130		if force {
131			removeEntireHooks(rawHooks)
132		}
133	
134		count := 0
135		for _, spec := range hookSpecs {
136			var matchers []grokHookMatcher
137			parseHookType(rawHooks, spec.GrokEvent, &matchers)
138			command := hookCommand(spec.HookName)
139			var changed bool
140			matchers, changed = upsertHook(matchers, spec.Matcher, spec.EntryName, command)
141			if changed {
142				count++
143			}
144			marshalHookType(rawHooks, spec.GrokEvent, matchers)
145		}
146	
147		if count == 0 && !force {
148			return 0, nil
149		}
150		return count, writeHookFile(path, rawHooks)
151	}
