153	func (a *Agent) UninstallHooks() error {
154		repoRoot := protocol.RepoRoot()
155		path := hooksFilePath(repoRoot)
156		if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
157			return nil
158		}
159		rawHooks, err := readHookFile(path)
160		if err != nil {
161			return err
162		}
163		removeEntireHooks(rawHooks)
164		return writeHookFile(path, rawHooks)
165	}
