321	func readHookFile(path string) (map[string]json.RawMessage, error) {
322		rawHooks := make(map[string]json.RawMessage)
323	
324		data, err := os.ReadFile(path)
325		if err != nil {
326			if errors.Is(err, os.ErrNotExist) {
327				return rawHooks, nil
328			}
329			return nil, err
330		}
331		if len(bytes.TrimSpace(data)) == 0 {
332			return rawHooks, nil
333		}
334		var root struct {
335			Hooks map[string]json.RawMessage `json:"hooks"`
336		}
337		if err := json.Unmarshal(data, &root); err != nil {
338			return nil, fmt.Errorf("parse %s: %w", path, err)
339		}
340		if root.Hooks != nil {
341			rawHooks = root.Hooks
342		}
343		return rawHooks, nil
344	}
