346	func writeHookFile(path string, rawHooks map[string]json.RawMessage) error {
347		root := map[string]any{"hooks": rawHooks}
348		data, err := json.MarshalIndent(root, "", "  ")
349		if err != nil {
350			return err
351		}
352		data = append(data, '\n')
353		if len(rawHooks) == 0 {
354			if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
355				return err
356			}
357			return nil
358		}
359		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
360			return err
361		}
362		return os.WriteFile(path, data, 0o600)
363	}
