390	func hookExists(matchers []grokHookMatcher, matcher string, entryName string) bool {
391		for _, m := range matchers {
392			if m.Matcher != matcher {
393				continue
394			}
395			for _, h := range m.Hooks {
396				if h.Type == "command" && h.Name == entryName && isEntireHook(h) {
397					return true
398				}
399			}
400		}
401		return false
402	}
