404	func upsertHook(matchers []grokHookMatcher, matcher string, entryName string, command string) ([]grokHookMatcher, bool) {
405		for i := range matchers {
406			if matchers[i].Matcher == matcher {
407				for j := range matchers[i].Hooks {
408					if isEntireHook(matchers[i].Hooks[j]) && matchers[i].Hooks[j].Name == entryName {
409						matchers[i].Hooks[j] = entireHookEntry(entryName, command)
410						return matchers, false
411					}
412				}
413				matchers[i].Hooks = append(matchers[i].Hooks, entireHookEntry(entryName, command))
414				return matchers, true
415			}
416		}
417		return append(matchers, grokHookMatcher{
418			Matcher: matcher,
419			Hooks:   []grokHookEntry{entireHookEntry(entryName, command)},
420		}), true
421	}
