432	func removeEntireHooks(rawHooks map[string]json.RawMessage) {
433		for _, spec := range hookSpecs {
434			var matchers []grokHookMatcher
435			parseHookType(rawHooks, spec.GrokEvent, &matchers)
436			matchers = removeEntireHooksFromMatchers(matchers)
437			marshalHookType(rawHooks, spec.GrokEvent, matchers)
438		}
439	}
440	
441	func removeEntireHooksFromMatchers(matchers []grokHookMatcher) []grokHookMatcher {
442		filteredMatchers := make([]grokHookMatcher, 0, len(matchers))
443		for _, matcher := range matchers {
444			filteredHooks := make([]grokHookEntry, 0, len(matcher.Hooks))
445			for _, hook := range matcher.Hooks {
446				if isEntireHook(hook) {
447					continue
448				}
449				filteredHooks = append(filteredHooks, hook)
450			}
451			if len(filteredHooks) == 0 {
452				continue
453			}
454			matcher.Hooks = filteredHooks
455			filteredMatchers = append(filteredMatchers, matcher)
456		}
457		return filteredMatchers
458	}
